function addProduct(){const d=document.createElement('div');d.className='product-row';d.innerHTML=`<label><span>${tr('food')}</span><input class="pn" list="foodSuggestions" placeholder="${tr('foodExample')}" autocomplete="off" required></label><label><span>${tr('weightGrams')}</span><div class="weight-input"><input class="pg" type="number" min="1" step="1" placeholder="200" required><b>g</b></div></label><div class="product-calculation">${tr('enterFoodWeight')}</div><button type="button" aria-label="${tr('removeProduct')}">×</button>`;d.querySelector('button').onclick=()=>{d.remove();mealTotals()};d.querySelectorAll('input').forEach(i=>i.oninput=()=>{calculateProductRow(d);mealTotals()});$('#productRows').appendChild(d);mealTotals()}
$('#addProduct').onclick=addProduct;function mealTotals(){const n=+$(`#myMealForm [name=servings]`).value||1,s=$$('.product-row').reduce((a,r)=>{for(const key of ['calories','protein','carbs','fat'])a[key]+=+r.dataset[key]||0;return a},{calories:0,protein:0,carbs:0,fat:0});$('#myMealTotals').innerHTML=`<div><span>${tr('perPortion')}</span><strong>${Math.round(s.calories/n)} kcal</strong></div><b>${Math.round(s.protein/n)}P · ${Math.round(s.carbs/n)}C · ${Math.round(s.fat/n)}F</b>`;return{s,n}}
$(`#myMealForm [name=servings]`).oninput=mealTotals;$('#myMealForm').onsubmit=e=>{e.preventDefault();$$('.product-row').forEach(calculateProductRow);if(!e.target.reportValidity())return;const f=new FormData(e.target),{s,n}=mealTotals(),ings=$$('.product-row').map(r=>({name:`${r.querySelector('.pn').value} · ${+r.querySelector('.pg').value} g`,grams:+r.querySelector('.pg').value,calories:+r.dataset.calories||0,protein:+r.dataset.protein||0,carbs:+r.dataset.carbs||0,fat:+r.dataset.fat||0}));state.myMeals.push({id:'m'+uid(),name:f.get('name'),category:f.get('category'),servings:n,calories:s.calories/n,protein:s.protein/n,carbs:s.carbs/n,fat:s.fat/n,ingredients:ings,custom:true});e.target.reset();e.target.servings.value=1;$('#productRows').innerHTML='';addProduct();closeModal('myMealModal');recipeCat='mine';save()};
function exerciseArt(type){const poses={bench:['M30 75h70','M48 70l16-20 22 8','M65 50v-20','M53 30h24','M55 84h35'],incline:['M35 78l50-35','M52 60l15-22 20 5','M68 38l2-17','M58 20h24'],pulldown:['M65 28v24','M40 18h50','M52 23l13 14 13-14','M65 52l-18 30','M65 52l18 30'],row:['M35 45l35 10 22-5','M70 55l-18 28','M70 55l18 28','M43 43l-12 18'],squat:['M65 25v25','M65 50l-20 22','M65 50l20 22','M45 72l-5 18','M85 72l8 18','M45 38h40'],rdl:['M45 30l22 25 25 2','M67 55l-15 32','M67 55l22 32','M30 58h65'],ohp:['M65 32v30','M65 62l-18 27','M65 62l18 27','M50 30l15-15 15 15','M45 14h40'],lateral:['M65 35v28','M65 63l-18 26','M65 63l18 26','M65 40L35 28','M65 40l30-12'],curl:['M65 30v35','M65 65l-18 24','M65 65l18 24','M65 42l-22 12 8 18','M65 42l22 12-8 18'],pushdown:['M65 30v35','M65 65l-18 24','M65 65l18 24','M65 42l-18 8 8 22','M65 42l18 8-8 22','M45 20h40'],plank:['M30 58l35-12 35 18','M65 46l-15 28','M100 64l12 18'],legraise:['M65 25v35','M65 60l25 10','M90 70l20-5','M65 42l-18 18','M65 42l18 18']};return `<svg viewBox="0 0 130 100" aria-label="Exercise illustration"><circle cx="65" cy="20" r="8"/><g>${(poses[type]||poses.bench).map(p=>`<path d="${p}"/>`).join('')}</g></svg>`}
function renderExercises(){$('#exerciseSummary').innerHTML=`<span>${EXERCISES.length} ${tr('guidedExercises')}</span><span>6 ${tr('muscleGroups')}</span>`;const labels={Chest:'Pecho',Back:'Espalda',Legs:'Piernas',Shoulders:'Hombros',Arms:'Brazos',Core:'Core'};$('#muscleFilter').options[0].textContent=tr('allMuscles');[...$('#muscleFilter').options].slice(1).forEach(o=>o.textContent=state.settings.language==='es'?(labels[o.value]||o.value):o.value);$('#exerciseSearch').placeholder=tr('searchExercises');const m=$('#muscleFilter').value,q=$('#exerciseSearch').value.toLowerCase();const list=EXERCISES.filter(x=>(m==='all'||x.muscle===m)&&exerciseText(x,'name').toLowerCase().includes(q));$('#exerciseGrid').innerHTML=list.map(x=>`<article class="exercise-card" role="button" tabindex="0" onclick="showExercise(${EXERCISES.indexOf(x)})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();showExercise(${EXERCISES.indexOf(x)})}"><div class="exercise-art"><img src="${x.image}" alt="${esc(exerciseText(x,'name'))}" loading="lazy" onerror="if(!this.dataset.fallback){this.dataset.fallback='1';this.src='https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?auto=format&fit=crop&w=900&q=80'}"></div><div class="exercise-body"><div class="recipe-meta"><span>${txt(x.muscle)}</span><span>${txt(x.level)}</span></div><h3>${esc(exerciseText(x,'name'))}</h3><div class="set-reps"><div><strong>${x.sets}</strong><span>${tr('sets')}</span></div><div><strong>${exerciseText(x,'reps')}</strong><span>${tr('reps')}</span></div></div><p>${esc(exerciseText(x,'cue'))}</p><small class="muted">${tr('generalStarting')}</small></div></article>`).join('')}
$('#muscleFilter').onchange=renderExercises;$('#exerciseSearch').oninput=renderExercises;
$('#openMeasurement').onclick=()=>{if(!$('#measurementForm [name=date]').value)$('#measurementForm [name=date]').value=today();openModal('measurementModal')};$('#measurementForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.bodyEntries.push({id:uid(),date:f.get('date'),weight:toLb(+f.get('weight')),bodyFat:+f.get('bodyFat')||null});e.target.reset();closeModal('measurementModal');save()};
function weightChangeDisplay(lb){const value=state.settings.units==='kg'?lb*0.453592:lb;return `${value>0?'+':''}${value.toFixed(1)} ${state.settings.units}`}
function renderProgress(){const rows=[...state.bodyEntries].sort((a,b)=>a.date.localeCompare(b.date)),last=rows.at(-1),first=rows[0],change=last&&first?last.weight-first.weight:0;$('#progressStats').innerHTML=`<div><span>${tr('currentWeight')}</span><strong>${last?weightDisplay(last.weight):'—'}</strong></div><div><span>${tr('goalWeight')}</span><strong>${state.goals.goalWeight?weightDisplay(state.goals.goalWeight):'—'}</strong></div><div><span>${tr('totalChange')}</span><strong>${rows.length>1?weightChangeDisplay(change):'—'}</strong></div><div><span>${tr('bodyFat')}</span><strong>${last?.bodyFat?last.bodyFat+'%':'—'}</strong></div>`;$('#measurementHistory').innerHTML=rows.length?[...rows].reverse().slice(0,8).map(r=>`<div class="history-row"><div><strong>${weightDisplay(r.weight)}</strong><span>${r.date}${r.bodyFat?' · '+r.bodyFat+'% BF':''}</span></div><button onclick="deleteMeasurement('${r.id}')">×</button></div>`).join(''):`<div class="empty">${tr('noMeasurements')}</div>`;drawChart(rows)}
window.deleteMeasurement=id=>{state.bodyEntries=state.bodyEntries.filter(x=>x.id!==id);save()};
function drawChart(rows){const c=$('#weightChart');if(!c)return;let filtered=rows;if($('#chartRange').value==='30'){const cutoff=new Date();cutoff.setDate(cutoff.getDate()-30);filtered=rows.filter(r=>new Date(r.date)>=cutoff)}const ratio=devicePixelRatio||1,w=c.width=c.clientWidth*ratio,h=c.height=280*ratio,ctx=c.getContext('2d'),p=35*ratio;ctx.clearRect(0,0,w,h);if(!filtered.length){ctx.fillStyle='#829087';ctx.font=`${14*ratio}px sans-serif`;ctx.fillText(tr('addMeasurementPrompt'),p,70*ratio);return}const vals=filtered.map(x=>x.weight),mn=Math.min(...vals)-2,mx=Math.max(...vals)+2;ctx.strokeStyle='#e3e8e4';for(let i=0;i<4;i++){let y=p+i*(h-2*p)/3;ctx.beginPath();ctx.moveTo(p,y);ctx.lineTo(w-p,y);ctx.stroke()}ctx.strokeStyle='#256c57';ctx.lineWidth=3*ratio;ctx.beginPath();filtered.forEach((r,i)=>{const x=p+i/Math.max(1,filtered.length-1)*(w-2*p),y=h-p-(r.weight-mn)/(mx-mn||1)*(h-2*p);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}
$('#chartRange').onchange=renderProgress;
$('#goalCalculator').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),sex=f.get('sex'),age=+f.get('age'),lb=toLb(+f.get('weight')),cm=state.settings.heightUnits==='cm'?+f.get('heightCm'):((+f.get('heightFt')*12)+(+f.get('heightIn')))*2.54,kg=lb*0.453592,activity=+f.get('activity'),goal=f.get('goal');let bmr=10*kg+6.25*cm-5*age+(sex==='male'?5:-161),tdee=bmr*activity,target=tdee+(goal==='lose'?-400:goal==='gain'?300:0);target=Math.round(target/10)*10;const protein=Math.round(kg*(goal==='lose'?1.8:1.6)),fat=Math.round((target*.27)/9),carbs=Math.max(0,Math.round((target-protein*4-fat*9)/4));state.profile={sex,age,weight:lb,heightCm:cm,activity,goal};state.goals={...state.goals,calories:target,protein,carbs,fat,goalWeight:toLb(+f.get('goalWeight')),waterGoal:+f.get('waterGoal')};closeModal('onboardingModal');save();renderGoalRecommendation(bmr,tdee)};
function renderGoalRecommendation(bmr,tdee){const g=state.goals;$('#goalRecommendation').innerHTML=`<p class="eyebrow">${tr('startingTarget')}</p><h2>${g.calories.toLocaleString()} kcal / ${tr('dayLower')}</h2><p class="muted">${tr('estimatedMaintenance')}: ${Math.round(tdee||g.calories).toLocaleString()} kcal</p><div class="goal-macros"><div><strong>${g.protein}g</strong><span>${tr('Protein')}</span></div><div><strong>${g.carbs}g</strong><span>${tr('Carbs')}</span></div><div><strong>${g.fat}g</strong><span>${tr('Fat')}</span></div></div><div class="goal-note"><strong>${tr('howEstimated')}</strong><p>${tr('estimateText')}</p></div>`}

